-- Zella - more industries (pet care, landscaping, pest control, spa, photography, property management, childcare, cleaning, insurance). Safe to run more than once.
-- Each gets its own wording, record types (CRM) and automation rules. Cleaning Services uses the Home Services records and rules; Insurance uses the Financial Services ones.
do $$
declare i_id uuid; r record; x record;
begin
  for x in select * from (values
    ('Pet Care & Veterinary', 'pet-care-veterinary', 'Vets, groomers and pet care', $t${"job":"Job","jobs":"Jobs","staff":"Team Member","visit":"Visit","visits":"Visits","service":"Pet Service","services":"Pet Services","customer":"Pet Owner","customers":"Pet Owners","appointment":"Appointment","appointments":"Appointments","staff_plural":"Team Members","voice":{"greeting":"Thank you for calling. I'm Zella, your virtual pet care receptionist. How can I help you and your pet today?","staff_role":"Team Member","caller_role":"Pet Owner","booking_action":"Appointment","primary_service":"Pet Care Visit"}}$t$::jsonb),
    ('Landscaping & Lawn Care', 'landscaping-lawn-care', 'Landscaping and lawn care businesses', $t${"job":"Job","jobs":"Jobs","staff":"Crew Member","visit":"Visit","visits":"Visits","service":"Lawn Service","services":"Lawn Services","customer":"Customer","customers":"Customers","appointment":"Service Visit","appointments":"Service Visits","staff_plural":"Crew","voice":{"greeting":"Thank you for calling. I'm Zella, your virtual receptionist for lawn and landscape care. How can I help?","staff_role":"Crew Member","caller_role":"Customer","booking_action":"Service Visit","primary_service":"Lawn Service"}}$t$::jsonb),
    ('Pest Control', 'pest-control', 'Pest control services', $t${"job":"Job","jobs":"Jobs","staff":"Technician","visit":"Visit","visits":"Visits","service":"Pest Service","services":"Pest Services","customer":"Customer","customers":"Customers","appointment":"Treatment Visit","appointments":"Treatment Visits","staff_plural":"Technicians","voice":{"greeting":"Thank you for calling. I'm Zella, your virtual pest control receptionist. How can I help you today?","staff_role":"Technician","caller_role":"Customer","booking_action":"Treatment Visit","primary_service":"Pest Service"}}$t$::jsonb),
    ('Spa & Wellness', 'spa-wellness', 'Spas, massage and wellness studios', $t${"job":"Job","jobs":"Jobs","staff":"Therapist","visit":"Visit","visits":"Visits","service":"Treatment","services":"Treatments","customer":"Client","customers":"Clients","appointment":"Appointment","appointments":"Appointments","staff_plural":"Therapists","voice":{"greeting":"Thank you for calling. I'm Zella, your virtual spa receptionist. How can I help you today?","staff_role":"Therapist","caller_role":"Client","booking_action":"Appointment","primary_service":"Treatment"}}$t$::jsonb),
    ('Photography & Events', 'photography-events', 'Photographers and event services', $t${"job":"Job","jobs":"Jobs","staff":"Photographer","visit":"Visit","visits":"Visits","service":"Shoot","services":"Shoots","customer":"Client","customers":"Clients","appointment":"Booking","appointments":"Bookings","staff_plural":"Photographers","voice":{"greeting":"Thank you for calling. I'm Zella, your virtual studio receptionist. How can I help you today?","staff_role":"Photographer","caller_role":"Client","booking_action":"Consultation","primary_service":"Photography Session"}}$t$::jsonb),
    ('Property Management', 'property-management', 'Landlords and property managers', $t${"job":"Job","jobs":"Jobs","staff":"Property Manager","visit":"Visit","visits":"Visits","service":"Property Service","services":"Property Services","customer":"Tenant","customers":"Tenants","appointment":"Viewing","appointments":"Viewings","staff_plural":"Property Managers","voice":{"greeting":"Thank you for calling. I'm Zella, your virtual property management receptionist. How can I help you today?","staff_role":"Property Manager","caller_role":"Tenant","booking_action":"Viewing","primary_service":"Property Service"}}$t$::jsonb),
    ('Childcare', 'childcare', 'Nurseries, daycares and preschools', $t${"job":"Job","jobs":"Jobs","staff":"Staff Member","visit":"Visit","visits":"Visits","service":"Childcare Place","services":"Childcare Places","customer":"Parent","customers":"Parents","appointment":"Tour","appointments":"Tours","staff_plural":"Staff","voice":{"greeting":"Thank you for calling. I'm Zella, your virtual childcare receptionist. How can I help you today?","staff_role":"Staff Member","caller_role":"Parent","booking_action":"Tour","primary_service":"Childcare Place"}}$t$::jsonb),
    ('Cleaning Services', 'cleaning-services', 'Home and office cleaning', $t${"job":"Job","jobs":"Jobs","staff":"Cleaner","visit":"Visit","visits":"Visits","service":"Cleaning Service","services":"Cleaning Services","customer":"Customer","customers":"Customers","appointment":"Cleaning Visit","appointments":"Cleaning Visits","staff_plural":"Cleaners","voice":{"greeting":"Thank you for calling. I'm Zella, your virtual cleaning services receptionist. How can I help you today?","staff_role":"Cleaner","caller_role":"Customer","booking_action":"Cleaning Visit","primary_service":"Cleaning Service"}}$t$::jsonb),
    ('Insurance', 'insurance', 'Insurance agencies and brokers', $t${"job":"Job","jobs":"Jobs","staff":"Advisor","visit":"Visit","visits":"Visits","service":"Insurance Service","services":"Insurance Services","customer":"Client","customers":"Clients","appointment":"Consultation","appointments":"Consultations","staff_plural":"Advisors","voice":{"greeting":"Thank you for calling. I'm Zella, your virtual insurance office receptionist. How can I help you today?","staff_role":"Advisor","caller_role":"Client","booking_action":"Consultation","primary_service":"Insurance Service"}}$t$::jsonb)
  ) as t(name, slug, description, terms) loop
    select id into i_id from public.industries where name = x.name;
    if i_id is null then insert into public.industries (name, slug, description, is_active) values (x.name, x.slug, x.description, true) returning id into i_id; end if;
    insert into public.industry_configurations (industry_id, terminology, statuses, features) select i_id, x.terms, '{}'::jsonb, '{}'::jsonb where not exists (select 1 from public.industry_configurations where industry_id = i_id);
    for r in select * from (values ('AI Receptionist','ai-receptionist','AI-powered receptionist and call handling'), ('AI Sales','ai-sales','AI-powered lead qualification and sales'), ('AI Support','ai-support','AI-powered customer support'), ('AI Follow-up','ai-follow-up','Automated customer follow-ups'), ('AI Appointments','ai-appointments','AI-powered appointment scheduling'), ('Calls','calls','Business phone and call management'), ('SMS','sms','Business messaging'), ('Email','email','Business email automation'), ('Calendar','calendar','Appointment and calendar management'), ('Automations','automations','Business workflow automation')) as t(name, slug, description) loop
      if not exists (select 1 from public.industry_modules where industry_id = i_id and slug = r.slug) then insert into public.industry_modules (industry_id, name, slug, description, is_active) values (i_id, r.name, r.slug, r.description, true); end if;
    end loop;
  end loop;
end $$;
-- cleaning maps onto the Home Services records
update public.industry_crm_presets set match = (select array_agg(distinct m) from unnest(match || array['cleaningservices']) m), updated_at = now() where key = 'home_services';
insert into public.industry_crm_presets (key, match, config) values
  ('pet_care', array['petcareveterinary','petcare','veterinary','vet','groomer'], $j${"types":[{"key":"pets","singular":"Pet","plural":"Pets","icon":"pets","title_label":"Pet name","link_person":true,"statuses":[{"key":"active","label":"Active","tone":"warning"},{"key":"inactive","label":"Inactive","tone":"success"}],"closed_statuses":["inactive"],"fields":[{"key":"species","label":"Species","type":"select","options":["Dog","Cat","Bird","Rabbit","Other"]},{"key":"breed","label":"Breed","type":"text"},{"key":"birthday","label":"Birthday","type":"date"},{"key":"notes","label":"Notes","type":"longtext"}],"columns":["species","breed"],"notice":null},{"key":"reminders","singular":"Reminder","plural":"Reminders","icon":"event_repeat","title_label":"Reminder","link_person":true,"statuses":[{"key":"due","label":"Due","tone":"warning"},{"key":"contacted","label":"Contacted","tone":"info"},{"key":"booked","label":"Booked","tone":"success"},{"key":"declined","label":"Declined","tone":""},{"key":"overdue","label":"Overdue","tone":"info"}],"closed_statuses":["booked","declined"],"fields":[{"key":"kind","label":"Type","type":"select","options":["Vaccination","Check-up","Grooming","Other"]},{"key":"due_date","label":"Due date","type":"date","required":true},{"key":"notes","label":"Notes","type":"longtext"}],"columns":["kind","due_date"],"notice":null}]}$j$::jsonb),
  ('landscaping', array['landscapinglawncare','landscaping','lawncare','gardening'], $j${"types":[{"key":"jobs","singular":"Job","plural":"Jobs","icon":"yard","title_label":"Job","link_person":true,"statuses":[{"key":"new","label":"New","tone":"warning"},{"key":"quoted","label":"Quote sent","tone":"info"},{"key":"approved","label":"Approved","tone":"info"},{"key":"scheduled","label":"Scheduled","tone":"info"},{"key":"in_progress","label":"In progress","tone":"info"},{"key":"completed","label":"Completed","tone":"success"},{"key":"cancelled","label":"Cancelled","tone":""}],"closed_statuses":["completed","cancelled"],"fields":[{"key":"address","label":"Address","type":"text"},{"key":"work","label":"Work","type":"select","options":["Mowing","Clean-up","Planting","Irrigation","Tree work","Other"]},{"key":"crew","label":"Crew","type":"text"},{"key":"scheduled_for","label":"Scheduled for","type":"datetime"},{"key":"details","label":"Details","type":"longtext"}],"columns":["address","work","scheduled_for"],"notice":null},{"key":"plans","singular":"Maintenance plan","plural":"Maintenance plans","icon":"event_repeat","title_label":"Plan","link_person":true,"statuses":[{"key":"active","label":"Active","tone":"warning"},{"key":"paused","label":"Paused","tone":"info"},{"key":"ended","label":"Ended","tone":"success"}],"closed_statuses":["ended"],"fields":[{"key":"plan","label":"Plan","type":"text"},{"key":"frequency","label":"Frequency","type":"select","options":["Weekly","Fortnightly","Monthly","Seasonal"]},{"key":"next_visit","label":"Next visit","type":"date"}],"columns":["plan","frequency","next_visit"],"notice":null}]}$j$::jsonb),
  ('pest_control', array['pestcontrol','pest','exterminator'], $j${"types":[{"key":"jobs","singular":"Job","plural":"Jobs","icon":"pest_control","title_label":"Job","link_person":true,"statuses":[{"key":"new","label":"New","tone":"warning"},{"key":"inspection_booked","label":"Inspection booked","tone":"info"},{"key":"quoted","label":"Quote sent","tone":"info"},{"key":"approved","label":"Approved","tone":"info"},{"key":"scheduled","label":"Scheduled","tone":"info"},{"key":"treated","label":"Treated","tone":"info"},{"key":"follow_up_due","label":"Follow-up due","tone":"info"},{"key":"completed","label":"Completed","tone":"success"},{"key":"cancelled","label":"Cancelled","tone":""}],"closed_statuses":["completed","cancelled"],"fields":[{"key":"address","label":"Address","type":"text"},{"key":"pest","label":"Pest","type":"select","options":["Rodents","Ants","Cockroaches","Wasps","Termites","Bed bugs","Other"]},{"key":"urgency","label":"Urgency","type":"select","options":["Routine","Urgent"]},{"key":"technician","label":"Technician","type":"text"},{"key":"scheduled_for","label":"Scheduled for","type":"datetime"}],"columns":["address","pest","urgency"],"notice":null},{"key":"plans","singular":"Service plan","plural":"Service plans","icon":"event_repeat","title_label":"Plan","link_person":true,"statuses":[{"key":"active","label":"Active","tone":"warning"},{"key":"due","label":"Visit due","tone":"info"},{"key":"ended","label":"Ended","tone":"success"}],"closed_statuses":["ended"],"fields":[{"key":"plan","label":"Plan","type":"text"},{"key":"next_visit","label":"Next visit","type":"date"}],"columns":["plan","next_visit"],"notice":null}]}$j$::jsonb),
  ('spa_wellness', array['spawellness','spa','wellness','massage'], $j${"types":[{"key":"packages","singular":"Package","plural":"Packages","icon":"spa","title_label":"Package","link_person":true,"statuses":[{"key":"active","label":"Active","tone":"warning"},{"key":"used_up","label":"Used up","tone":"success"},{"key":"expired","label":"Expired","tone":"success"}],"closed_statuses":["used_up","expired"],"fields":[{"key":"package","label":"Package","type":"text"},{"key":"sessions_left","label":"Sessions left","type":"number"},{"key":"expires","label":"Expires","type":"date"}],"columns":["package","sessions_left","expires"],"notice":null},{"key":"memberships","singular":"Membership","plural":"Memberships","icon":"loyalty","title_label":"Membership","link_person":true,"statuses":[{"key":"active","label":"Active","tone":"warning"},{"key":"paused","label":"Paused","tone":"info"},{"key":"ended","label":"Ended","tone":"success"}],"closed_statuses":["ended"],"fields":[{"key":"plan","label":"Plan","type":"text"},{"key":"renews","label":"Renews","type":"date"}],"columns":["plan","renews"],"notice":null}]}$j$::jsonb),
  ('photography_events', array['photographyevents','photography','photographer','eventplanning'], $j${"types":[{"key":"bookings","singular":"Booking","plural":"Bookings","icon":"photo_camera","title_label":"Booking","link_person":true,"statuses":[{"key":"enquiry","label":"Enquiry","tone":"warning"},{"key":"quoted","label":"Quote sent","tone":"info"},{"key":"booked","label":"Booked","tone":"info"},{"key":"shoot_done","label":"Shoot done","tone":"info"},{"key":"editing","label":"Editing","tone":"info"},{"key":"delivered","label":"Delivered","tone":"success"},{"key":"cancelled","label":"Cancelled","tone":""}],"closed_statuses":["delivered","cancelled"],"fields":[{"key":"kind","label":"Type","type":"select","options":["Wedding","Portrait","Event","Commercial","Other"]},{"key":"event_date","label":"Date","type":"datetime"},{"key":"location","label":"Location","type":"text"},{"key":"details","label":"Details","type":"longtext"}],"columns":["kind","event_date","location"],"notice":null}]}$j$::jsonb),
  ('property_management', array['propertymanagement','propertymanager','landlord'], $j${"types":[{"key":"requests","singular":"Maintenance request","plural":"Maintenance requests","icon":"build","title_label":"Request","link_person":true,"statuses":[{"key":"new","label":"New","tone":"warning"},{"key":"assigned","label":"Assigned","tone":"info"},{"key":"scheduled","label":"Scheduled","tone":"info"},{"key":"in_progress","label":"In progress","tone":"info"},{"key":"completed","label":"Completed","tone":"success"},{"key":"cancelled","label":"Cancelled","tone":""}],"closed_statuses":["completed","cancelled"],"fields":[{"key":"unit","label":"Unit or address","type":"text"},{"key":"category","label":"Category","type":"select","options":["Plumbing","Electrical","Heating and cooling","Appliance","Other"]},{"key":"priority","label":"Priority","type":"select","options":["Routine","Urgent","Emergency"]},{"key":"access","label":"Permission to enter","type":"select","options":["Yes","No","Ask first"]},{"key":"details","label":"Details","type":"longtext"}],"columns":["unit","category","priority"],"notice":null},{"key":"leases","singular":"Lease","plural":"Leases","icon":"description","title_label":"Lease","link_person":true,"statuses":[{"key":"active","label":"Active","tone":"warning"},{"key":"renewal_due","label":"Renewal due","tone":"info"},{"key":"ending","label":"Ending","tone":"info"},{"key":"ended","label":"Ended","tone":"success"}],"closed_statuses":["ended"],"fields":[{"key":"unit","label":"Unit or address","type":"text"},{"key":"starts","label":"Starts","type":"date"},{"key":"ends","label":"Ends","type":"date"}],"columns":["unit","starts","ends"],"notice":null}]}$j$::jsonb),
  ('childcare', array['childcare','daycare','nursery','preschool'], $j${"types":[{"key":"enrolments","singular":"Enrolment","plural":"Enrolments","icon":"child_care","title_label":"Family","link_person":true,"statuses":[{"key":"enquiry","label":"Enquiry","tone":"warning"},{"key":"tour_booked","label":"Tour booked","tone":"info"},{"key":"waitlist","label":"Waitlist","tone":"info"},{"key":"enrolled","label":"Enrolled","tone":"success"},{"key":"withdrawn","label":"Withdrawn","tone":""}],"closed_statuses":["enrolled","withdrawn"],"fields":[{"key":"child_first_name","label":"Child's first name","type":"text"},{"key":"age_group","label":"Age group","type":"select","options":["Baby","Toddler","Preschool","School age"]},{"key":"start_date","label":"Start date","type":"date"},{"key":"notes","label":"Notes","type":"longtext"}],"columns":["child_first_name","age_group","start_date"],"notice":"Keep notes to what is needed to run the place. Never share a child's details with anyone except a verified parent or guardian."}]}$j$::jsonb)
on conflict (key) do update set match = excluded.match, config = excluded.config, updated_at = now();
